        if ok and all(v==filled[j] for j in range(n)):
            return filled,p
    return None,None
res=[]
for i,r in enumerate(T):
    f,p=row_fill(r)
    res.append((i,f,p))
print(len(res), sum(1 for x in res if x[1]), [ (x[0],x[2]) for x in res if x[1]][:5])
